import { AUTH_SUBMIT_SELECTOR, ORDER_FLOW, availabilityMessage, canDeliver, cartLines, cartTotals, createRequestKey, currentSelections, estimatedMargin, money, nextOrderStatuses, orderItemPayload, recognisedCommission, restaurantMatches, serializeModifierRows, serializeOpeningRows, statusLabel, validateModifierSelection } from "./model.js";

const main = document.querySelector("#main");
const account = document.querySelector("#account");
const toast = document.querySelector("#toast");
const state = { user: null, view: "discover", restaurants: [], selected: null, menu: [], cart: {}, modifiers: {}, fulfillment: "delivery", fulfillmentExplicit: false, postcode: "", search: "", cuisine: "", orders: [], offers: [], selectedOffer: null, notifications: [], unreadCount: 0, workspace: {}, generation: 0, poll: null, notificationPoll: null, orderKey: null, submitting: false, pendingCheckout: false, dialogReturnFocus: null };
const e = (value) => String(value ?? "").replace(/[&<>"']/g, (char) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[char]);
const shortId = (id) => id ? id.slice(0, 8).toUpperCase() : "—";
const date = (value) => new Intl.DateTimeFormat("en-GB", { dateStyle: "medium", timeStyle: "short" }).format(new Date(value));
const message = (text) => { toast.textContent = text; toast.classList.add("show"); clearTimeout(message.timer); message.timer = setTimeout(() => toast.classList.remove("show"), 3500); };

async function api(path, options = {}) {
  const headers = { Accept: "application/json", ...(options.body ? { "Content-Type": "application/json" } : {}), ...options.headers };
  const response = await fetch(path, { credentials: "same-origin", ...options, headers });
  const type = response.headers.get("content-type") ?? "";
  const body = type.includes("json") ? await response.json() : null;
  if (!response.ok) throw new Error(body?.error?.message ?? `Request failed (${response.status})`);
  return body?.data;
}

function loading(label = "Loading") { main.innerHTML = `<section class="section"><div class="empty" role="status">${e(label)}…</div></section>`; }
function showError(error, retry = "") { main.innerHTML = `<section class="section"><div class="error" role="alert"><strong>We couldn’t load this.</strong><br>${e(error.message)}</div>${retry ? `<button class="primary" data-action="${e(retry)}">Try again</button>` : ""}</section>`; }
function setAccount() {
  account.innerHTML = state.user ? `<button class="notification-bell" data-action="notifications" aria-label="Notifications, ${state.unreadCount} unread"><svg viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/></svg>${state.unreadCount ? `<b>${state.unreadCount}</b>` : ""}</button><button class="account-button" data-action="logout">${e(state.user.name)} · Sign out</button>` : `<button class="account-button" data-action="auth">Sign in</button>`;
  document.querySelectorAll(".topbar [data-view]").forEach((node) => {
    const needsAccount = node.dataset.view !== "discover";
    const customerWorkspace = node.dataset.view === "workspace" && state.user?.role === "customer";
    const customerOnly = ["orders", "offers"].includes(node.dataset.view) && state.user?.role !== "customer";
    node.toggleAttribute("hidden", (needsAccount && !state.user) || customerWorkspace || customerOnly);
  });
  document.querySelector("#customer-bottom")?.toggleAttribute("hidden", state.user?.role !== "customer");
}
function stopPolling() { if (state.poll) clearInterval(state.poll); if (state.notificationPoll) clearInterval(state.notificationPoll); state.poll = null; state.notificationPoll = null; }
function stopOrderPolling() { if (state.poll) clearInterval(state.poll); state.poll = null; }
function resetIdentity(user) { stopPolling(); clearTimeout(message.timer); toast.textContent = ""; toast.classList.remove("show"); state.generation += 1; state.user = user; state.orders = []; state.offers = []; state.selectedOffer = null; state.notifications = []; state.unreadCount = 0; state.workspace = {}; state.orderKey = null; setAccount(); if (user) { loadNotifications(); state.notificationPoll = setInterval(loadNotifications, 10000); } }

async function boot() {
  setAccount();
  try { const result = await api("/api/auth/me"); resetIdentity(result.user); } catch { resetIdentity(null); }
  await navigate("discover");
}

async function navigate(view) {
  if (view !== "orders") stopOrderPolling();
  state.view = view;
  document.querySelectorAll("[data-view]").forEach((node) => node.setAttribute("aria-current", node.dataset.view === view ? "page" : "false"));
  if (view === "discover") return loadDiscover();
  if (!state.user) return renderAuth();
  if (view === "orders") return state.user.role === "customer" ? loadOrders() : renderDenied("Order history is for customer accounts.");
  if (view === "offers") return state.user.role === "customer" ? loadOffers() : renderDenied("Offers are for customer accounts.");
  if (view === "account") return loadAccount();
  if (view === "workspace") return loadWorkspace();
}

async function loadDiscover() {
  loading("Finding local food");
  const params = new URLSearchParams(); params.set("fulfillment", state.fulfillment); if (state.postcode) params.set("postcode", state.postcode); if (state.search) params.set("q", state.search); if (state.cuisine) params.set("cuisine", state.cuisine);
  try { state.restaurants = await api(`/api/restaurants${params.size ? `?${params}` : ""}`); renderDiscover(); } catch (error) { showError(error, "reload-discover"); }
}

function renderDiscover() {
  const filtered = state.restaurants.filter((r) => restaurantMatches(r, state.search, state.postcode, state.fulfillment)); const cuisines = [...new Set(state.restaurants.map((r) => r.profile?.cuisine).filter(Boolean))];
  main.innerHTML = `<section class="customer-hero"><div class="customer-head"><div><span class="eyebrow">${state.fulfillment === "delivery" ? "Deliver now" : "Collection"}</span><h1>${state.postcode ? e(state.postcode.toUpperCase()) : "Choose your address"}</h1></div><div class="fulfillment-switch"><button data-action="quick-fulfillment" data-value="delivery" class="${state.fulfillment === "delivery" ? "active" : ""}">Delivery</button><button data-action="quick-fulfillment" data-value="collection" class="${state.fulfillment === "collection" ? "active" : ""}">Collection</button></div></div><form class="address-search" id="postcode-form"><label for="postcode">Delivery postcode</label><div><input id="postcode" name="postcode" autocomplete="postal-code" placeholder="Enter LU1 or LU2" value="${e(state.postcode)}"><button>Update</button></div></form><label class="customer-search"><span aria-hidden="true">⌕</span><input id="restaurant-search" type="search" value="${e(state.search)}" placeholder="Search restaurants, cuisines or dishes"></label><div class="cuisine-chips"><button class="chip ${!state.cuisine ? "active" : ""}" data-action="cuisine-chip" data-value="">All</button>${cuisines.map((c) => `<button class="chip ${c === state.cuisine ? "active" : ""}" data-action="cuisine-chip" data-value="${e(c)}">${e(c)}</button>`).join("")}</div></section>
  <section class="section customer-results"><div class="section-head"><div><h2>${state.postcode && state.fulfillment === "delivery" ? `Food delivered to ${e(state.postcode.toUpperCase())}` : "Restaurants near Luton"}</h2><p class="meta">Real availability and current restaurant settings</p></div></div>
  ${filtered.length ? `<div class="restaurant-grid">${filtered.map((r) => { const unavailable = availabilityMessage(r, state.fulfillment); const estimate = state.fulfillment === "delivery" ? r.profile?.estimatedDeliveryMinutes : r.profile?.estimatedCollectionMinutes; return `<article class="restaurant-tile"><button class="restaurant-open" data-action="open-menu" data-id="${e(r.id)}"><figure class="restaurant-photo"><img src="/assets/food-demo.png" alt="Illustrative demo food for ${e(r.name)}"><figcaption>Illustrative demo photo</figcaption></figure><div class="restaurant-copy"><div><span class="badge">${e(r.profile?.cuisine || "Local food")}</span><h3>${e(r.name)}</h3></div><span class="estimate">${estimate ? `${e(estimate)} min` : "See menu"}</span><p>${e(r.profile?.description || "Explore the restaurant’s current menu.")}</p><div class="restaurant-facts"><span>${state.fulfillment === "delivery" ? `${money(r.delivery?.deliveryFeeMinor ?? 0)} delivery` : "Collection"}</span>${state.fulfillment === "delivery" ? `<span>${money(r.delivery?.minDeliverySubtotalMinor ?? 0)} minimum</span>` : ""}</div>${unavailable ? `<span class="closed-label">${e(unavailable)}</span>` : ""}</div></button></article>`; }).join("")}</div>` : `<div class="empty"><strong>No matching restaurants yet.</strong><p>Try another search, cuisine or fulfillment option. Coverage is shown only where restaurants have configured it.</p><button class="secondary" data-action="clear-filters">Show all restaurants</button></div>`}</section>`;
}

async function openMenu(id) {
  loading("Opening menu");
  try { const data = await api(`/api/restaurants/${encodeURIComponent(id)}/menu`); state.selected = data.restaurant; state.menu = data.items; state.cart = {}; state.modifiers = {}; state.fulfillment = state.postcode && !state.fulfillmentExplicit ? "delivery" : state.fulfillment; renderMenu(); } catch (error) { showError(error, "reload-discover"); }
}

function modifierGroupsHtml(item) {
  return (item.modifierGroups ?? []).map((group) => { const selected = state.modifiers[item.id]?.[group.id] ?? []; const clearChoice = group.minSelections === 0 && group.maxSelections === 1 ? `<label class="modifier-option"><input type="radio" name="modifier-${e(item.id)}-${e(group.id)}" data-modifier-item="${e(item.id)}" data-modifier-group="${e(group.id)}" value="" ${selected.length ? "" : "checked"}> <span>No selection</span></label>` : ""; return `<fieldset class="modifier-group"><legend>${e(group.name)} ${group.minSelections ? `<span class="badge">Required</span>` : `<span class="meta">Optional</span>`}</legend><p class="meta">Choose ${group.minSelections}${group.maxSelections !== group.minSelections ? `–${group.maxSelections}` : ""}</p>${clearChoice}${group.options.map((option) => { const chosen = selected.includes(option.id); const type = group.maxSelections === 1 ? "radio" : "checkbox"; return `<label class="modifier-option"><input type="${type}" name="modifier-${e(item.id)}-${e(group.id)}" data-modifier-item="${e(item.id)}" data-modifier-group="${e(group.id)}" value="${e(option.id)}" ${chosen ? "checked" : ""} ${option.available ? "" : "disabled"}> <span>${e(option.name)} ${option.priceMinor ? `+${money(option.priceMinor)}` : ""}${option.available ? "" : " · unavailable"}</span></label>`; }).join("")}</fieldset>`; }).join("");
}
function selectedModifierNames(line) { return (line.modifiers ?? []).flatMap((selection) => { const group=line.modifierGroups?.find((candidate)=>candidate.id===selection.groupId); return selection.optionIds.map((id)=>group?.options.find((option)=>option.id===id)?.name).filter(Boolean); }); }

function renderMenu() {
  const lines = cartLines(state.menu, state.cart, state.modifiers); const totals = cartTotals(lines, state.fulfillment, state.selected.delivery); const unavailable = availabilityMessage(state.selected, state.fulfillment);
  main.innerHTML = `<section class="menu-banner"><img src="/assets/food-demo.png" alt="Illustrative demo food"><span>Illustrative demo photo</span></section><section class="section menu-page"><button class="quiet" data-action="back-discover">← Restaurants</button><div class="section-head"><div><div class="eyebrow">${e(state.selected.profile?.cuisine || "Local menu")}</div><h1>${e(state.selected.name)}</h1><p class="meta">${state.fulfillment === "delivery" ? `${e(state.selected.profile?.estimatedDeliveryMinutes ?? "—")} min · ${money(state.selected.delivery.deliveryFeeMinor)} delivery · ${money(state.selected.delivery.minDeliverySubtotalMinor)} minimum` : `${e(state.selected.profile?.estimatedCollectionMinutes ?? "—")} min collection`}</p></div></div><div class="layout"><div class="card"><h2>Menu</h2>${state.menu.length ? state.menu.map((item) => `<div class="menu-row"><div class="menu-item-copy"><span class="badge">${e(item.category || "Menu")}</span><h3>${e(item.name)}</h3><p class="meta">${e(item.description || "Prepared by the restaurant")}</p>${item.dietaryTags?.length ? `<p class="meta">${item.dietaryTags.map(e).join(" · ")}</p>` : ""}${item.allergens?.length ? `<p class="allergy"><strong>Allergens:</strong> ${item.allergens.map(e).join(", ")} <span>Restaurant supplied</span></p>` : `<p class="meta">Ask the restaurant about allergens before ordering.</p>`}<strong>${money(item.priceMinor)}</strong>${modifierGroupsHtml(item)}</div><div class="menu-item-action"><div class="menu-thumb" aria-hidden="true">${item.category?.toLowerCase().includes("drink") ? "🥤" : "🍽️"}</div><div class="qty" aria-label="Quantity for ${e(item.name)}"><button data-action="qty" data-id="${e(item.id)}" data-delta="-1" aria-label="Remove one ${e(item.name)}">−</button><span>${state.cart[item.id] ?? 0}</span><button data-action="qty" data-id="${e(item.id)}" data-delta="1" aria-label="Add one ${e(item.name)}">+</button></div></div></div>`).join("") : `<div class="empty">This restaurant has no available items right now.</div>`}</div>
  <aside class="card cart mobile-basket" aria-label="Basket"><h2>Your basket</h2>${unavailable ? `<div class="error">${e(unavailable)}</div>` : ""}${lines.length ? lines.map((line) => `<p class="cart-line"><span>${line.quantity} × ${e(line.name)}</span><strong>${money(line.lineTotalMinor)}</strong></p>`).join("") : `<p class="muted">Add an item to get started.</p>`}<div class="radio-row"><label class="radio-card"><input type="radio" name="fulfillment" value="collection" ${state.fulfillment === "collection" ? "checked" : ""} ${state.selected.profile?.collectionEnabled === false ? "disabled" : ""}> Collection</label><label class="radio-card"><input type="radio" name="fulfillment" value="delivery" ${state.fulfillment === "delivery" ? "checked" : ""} ${state.selected.delivery.enabled ? "" : "disabled"}> Delivery</label></div><div class="totals"><div><span>Food</span><span>${money(totals.subtotalMinor)}</span></div><div><span>Delivery fee</span><span>${money(totals.deliveryFeeMinor)}</span></div><div><span>Platform fee</span><span>£0.00</span></div><div class="grand"><span>Total</span><span>${money(totals.totalMinor)}</span></div></div><div class="card-actions"><button class="primary basket-cta" data-action="checkout" ${lines.length && !unavailable ? "" : "disabled"}>Go to checkout · ${money(totals.totalMinor)}</button></div></aside></div></section>`;
}

function renderCheckout() {
  if (!state.user) { state.pendingCheckout = true; return renderAuth("Sign in or create a customer account to place this order."); }
  if (state.user.role !== "customer") return renderDenied("Only customer accounts can place orders.");
  const lines = cartLines(state.menu, state.cart, state.modifiers); const totals = cartTotals(lines, state.fulfillment, state.selected.delivery);
  const invalid = lines.map((line) => validateModifierSelection(line, state.modifiers[line.id])).find((result) => !result.ok);
  if (invalid) { message(invalid.reason); return renderMenu(); }
  main.innerHTML = `<section class="section"><button class="quiet" data-action="back-menu">← Menu</button><div class="section-head"><div><div class="eyebrow">Checkout</div><h1>Finish your order</h1></div><strong>${money(totals.totalMinor)}</strong></div><form id="checkout-form" class="card stack"><div class="notice">Mock card is for this local demo and never contacts a payment provider. Cash is paid directly to the restaurant.</div><label>Contact phone<input class="field" name="customerPhone" type="tel" autocomplete="tel" maxlength="30"></label>${state.fulfillment === "delivery" ? `<fieldset class="form-grid"><legend>Delivery address</legend><label>Address line 1<input class="field" name="line1" required autocomplete="address-line1"></label><label>Address line 2<input class="field" name="line2" autocomplete="address-line2"></label><label>Town or city<input class="field" name="city" value="Luton" required autocomplete="address-level2"></label><label>Postcode<input class="field" name="postcode" value="${e(state.postcode)}" required autocomplete="postal-code"></label><label class="full">Delivery instructions<textarea name="deliveryInstructions" maxlength="500" placeholder="Door, access or hand-off details"></textarea></label></fieldset>` : `<p><strong>Collection</strong> from ${e(state.selected.name)}</p>`}<label class="allergy-note">Allergy notes<textarea name="allergyNotes" maxlength="500" placeholder="Tell the restaurant about allergies. Contact them if you are unsure."></textarea></label><fieldset><legend>Payment</legend><div class="radio-row"><label class="radio-card"><input type="radio" name="paymentMethod" value="mock_card" checked> Mock card (demo only)</label><label class="radio-card"><input type="radio" name="paymentMethod" value="cash" ${state.selected.profile?.cashEnabled === false ? "disabled" : ""}> ${state.fulfillment === "delivery" ? "Cash on delivery" : "Cash on collection"} ${state.selected.profile?.cashEnabled === false ? "(unavailable)" : ""}</label></div></fieldset><div class="totals"><div><span>Food</span><span>${money(totals.subtotalMinor)}</span></div><div><span>Delivery</span><span>${money(totals.deliveryFeeMinor)}</span></div><div class="grand"><span>Order total</span><span>${money(totals.totalMinor)}</span></div></div><div id="checkout-error"></div><button class="primary" id="place-order">Place order</button></form></section>`;
  document.querySelector("#checkout-form").insertAdjacentHTML("afterbegin", `<div class="checkout-items"><strong>Your order</strong>${lines.map((line)=>{const choices=selectedModifierNames(line);return `<p><span>${line.quantity} × ${e(line.name)}${choices.length?` · ${choices.map(e).join(", ")}`:""}</span><b>${money(line.lineTotalMinor)}</b></p>`;}).join("")}</div>`);
  if (state.selectedOffer?.restaurantId === state.selected.id) document.querySelector("#checkout-form").insertAdjacentHTML("afterbegin", `<div class="offer-summary"><strong>Free ${e(state.selectedOffer.itemName)}</strong><span>${e(state.selectedOffer.title)} · no extra charge</span><small>Applies when paid food reaches ${money(state.selectedOffer.minSubtotalMinor)}. Eligibility is checked when you place the order.</small></div>`);
}

async function submitOrder(form) {
  if (state.submitting) return; state.submitting = true;
  const button = form.querySelector("button[type=submit],#place-order"); button.disabled = true; button.textContent = "Placing order…";
  const data = new FormData(form); const lines = cartLines(state.menu, state.cart, state.modifiers);
  const body = { restaurantId: state.selected.id, items: orderItemPayload(lines), paymentMethod: data.get("paymentMethod"), fulfillment: state.fulfillment, ...(state.selectedOffer?.restaurantId === state.selected.id ? { offerId: state.selectedOffer.id } : {}), ...(data.get("customerPhone") ? { customerPhone: data.get("customerPhone") } : {}), ...(data.get("deliveryInstructions") ? { deliveryInstructions: data.get("deliveryInstructions") } : {}), ...(data.get("allergyNotes") ? { allergyNotes: data.get("allergyNotes") } : {}) };
  if (state.fulfillment === "delivery") body.deliveryAddress = { line1: data.get("line1"), ...(data.get("line2") ? { line2: data.get("line2") } : {}), city: data.get("city"), postcode: data.get("postcode") };
  state.orderKey ??= createRequestKey();
  try { const order = await api("/api/orders", { method: "POST", headers: { "Idempotency-Key": state.orderKey }, body: JSON.stringify(body) }); state.orderKey = null; state.cart = {}; state.selectedOffer = null; renderConfirmation(order); }
  catch (error) { const box = document.querySelector("#checkout-error"); box.className = "error"; box.textContent = `${error.message} You can retry safely; the same request key will be used.`; button.disabled = false; button.textContent = "Retry order"; }
  finally { state.submitting = false; }
}

function renderConfirmation(order) { main.innerHTML = `<section class="section"><div class="card"><div class="food-mark" aria-hidden="true">✓</div><div class="eyebrow">Order received</div><h1>Thanks, ${e(state.user.name)}.</h1><p>${e(order.restaurantName)} has your ${e(order.fulfillment)} order. Reference <strong>${e(shortId(order.id))}</strong>.</p><p class="badge">${e(statusLabel(order.status))}</p><div class="totals"><div class="grand"><span>Total</span><span>${money(order.totalMinor)}</span></div></div><div class="card-actions"><button class="primary" data-view="orders">Track order</button><button class="secondary" data-action="print-receipt" data-id="${e(order.id)}">Print receipt</button></div></div></section>`; }

function renderAuth(note = "") {
  stopPolling(); main.innerHTML = `<section class="section"><div class="section-head"><div><div class="eyebrow">Your account</div><h1>Sign in to Calai Eats</h1></div></div>${note ? `<div class="notice">${e(note)}</div>` : ""}<div class="grid"><form class="card stack" id="login-form"><h2>Welcome back</h2><label>Email<input class="field" name="email" type="email" required autocomplete="email"></label><label>Password<input class="field" name="password" type="password" minlength="12" required autocomplete="current-password"></label><div class="form-error"></div><button class="primary">Sign in</button><p class="muted">Local demo shortcuts</p><div class="card-actions"><button type="button" class="secondary" data-demo="customer">Customer demo</button><button type="button" class="secondary" data-demo="restaurant">Restaurant demo</button><button type="button" class="secondary" data-demo="admin">Admin demo</button></div></form><form class="card stack" id="register-form"><h2>Create a customer account</h2><label>Name<input class="field" name="name" required autocomplete="name"></label><label>Email<input class="field" name="email" type="email" required autocomplete="email"></label><label>Password<input class="field" name="password" type="password" minlength="12" required autocomplete="new-password"></label><div class="form-error"></div><button class="primary">Create account</button></form><form class="card stack" id="restaurant-register-form"><h2>List your restaurant</h2><label>Your name<input class="field" name="name" required autocomplete="name"></label><label>Restaurant name<input class="field" name="restaurantName" required></label><label>Email<input class="field" name="email" type="email" required autocomplete="email"></label><label>Password<input class="field" name="password" type="password" minlength="12" required autocomplete="new-password"></label><div class="form-error"></div><button class="primary">Create pending application</button><p class="muted">Registration starts an admin-reviewed application. It does not publish the restaurant.</p></form></div><p class="muted">Demo buttons use public local fixture accounts.</p></section>`;
}

async function authSubmit(form, register = false) {
  const data = Object.fromEntries(new FormData(form)); const button = form.querySelector(AUTH_SUBMIT_SELECTOR); button.disabled = true;
  try { const result = await api(`/api/auth/${register ? "register" : "login"}`, { method: "POST", body: JSON.stringify(data) }); const resumeCheckout = state.pendingCheckout && result.user.role === "customer"; resetIdentity(result.user); if (resumeCheckout) { state.pendingCheckout = false; renderCheckout(); } else await navigate(result.user.role === "customer" ? "discover" : "workspace"); }
  catch (error) { const box = form.querySelector(".form-error"); box.className = "form-error error"; box.textContent = error.message; button.disabled = false; }
}

async function demoLogin(role) {
  const credentials = { customer: ["customer@calai.local", "LocalCustomer!4310"], restaurant: ["restaurant@calai.local", "LocalRestaurant!4310"], admin: ["admin@calai.local", "LocalAdmin!4310"] }[role];
  try { const result = await api("/api/auth/login", { method: "POST", body: JSON.stringify({ email: credentials[0], password: credentials[1] }) }); const resumeCheckout = state.pendingCheckout && result.user.role === "customer"; resetIdentity(result.user); if (resumeCheckout) { state.pendingCheckout = false; renderCheckout(); } else await navigate(role === "customer" ? "discover" : "workspace"); } catch (error) { message(error.message); }
}

async function loadNotifications() {
  const generation = state.generation;
  try { const data = await api("/api/notifications"); if (generation !== state.generation || !state.user) return; state.notifications = data.items; state.unreadCount = data.unreadCount; setAccount(); } catch { /* keep the current inbox state during a transient failure */ }
}
function showNotifications() {
  showDialog(`<h2 id="dialog-title" tabindex="-1">Notifications</h2>${state.notifications.length ? `<div class="notification-list">${state.notifications.map((n) => `<article class="notification ${n.readAt ? "" : "unread"}"><h3>${e(n.title)}</h3><p>${e(n.message)}</p><small>${date(n.createdAt)}${n.orderId ? ` · Order ${e(shortId(n.orderId))}` : ""}</small><div class="card-actions">${n.readAt ? "" : `<button class="secondary" data-action="mark-notification" data-id="${e(n.id)}">Mark read</button>`}${n.orderId ? `<button class="secondary" data-action="notification-order" data-id="${e(n.id)}">Open order</button>` : ""}${n.offerId ? `<button class="secondary" data-action="notification-offer" data-id="${e(n.id)}" data-offer="${e(n.offerId)}">Open offer</button>` : ""}</div></article>`).join("")}</div>` : `<div class="empty">No notifications yet.</div>`}`);
}
async function loadOffers() {
  loading("Loading offers"); const generation = state.generation;
  try { state.offers = await api("/api/offers"); if (generation !== state.generation) return; renderOffers(); } catch (error) { showError(error); }
}
function renderOffers() {
  main.innerHTML = `<section class="section"><div class="section-head"><div><div class="eyebrow">Funded by restaurants</div><h1>Your offers</h1><p class="meta">One offer can be used per qualifying order.</p></div></div><div class="grid">${state.offers.length ? state.offers.map((offer) => `<article class="card offer-card"><span class="badge">${e(statusLabel(offer.status))}</span><h2>${e(offer.title)}</h2><p>${e(offer.message)}</p><p><strong>Free ${e(offer.itemName)}</strong> with ${money(offer.minSubtotalMinor)} paid food minimum.</p><p class="meta">${e(offer.restaurantName)} · expires ${date(offer.expiresAt)}</p><button class="primary" data-action="choose-offer" data-id="${e(offer.id)}" ${offer.status === "available" ? "" : "disabled"}>Choose this offer</button></article>`).join("") : `<div class="empty">No offers are available right now.</div>`}</div></section>`;
}
async function chooseOffer(id) {
  const offer = state.offers.find((entry) => entry.id === id); if (!offer) return;
  try { await api(`/api/offers/${encodeURIComponent(id)}`, { method:"PATCH", body:JSON.stringify({ viewed:true }) }); state.selectedOffer = offer; await openMenu(offer.restaurantId); message(`Offer selected: free ${offer.itemName}. Add ${money(offer.minSubtotalMinor)} of paid food to use it.`); } catch(error) { message(error.message); }
}

async function loadAccount() {
  stopOrderPolling(); loading("Loading account"); const generation = state.generation;
  try { const [profile, support, deletion] = await Promise.all([api("/api/account"), api("/api/support").catch(() => []), api("/api/account/deletion-requests").catch(() => [])]); if (generation !== state.generation) return; state.workspace.account = { profile, support, deletion }; renderAccount(); } catch (error) { showError(error); }
}
function renderAccount() {
  const { profile, support, deletion } = state.workspace.account;
  main.innerHTML = `<section class="section"><div class="section-head"><div><div class="eyebrow">Account</div><h1>Your details & support</h1></div><a class="secondary" href="/api/account/export" target="_blank" rel="noopener">Download my data</a></div><div class="grid"><form id="account-form" class="card stack"><h2>Profile</h2><label>Name<input class="field" name="name" value="${e(profile.name)}" required></label><label>Phone<input class="field" name="phone" type="tel" value="${e(profile.phone || "")}"></label><p class="meta">${e(profile.email)} · ${e(statusLabel(profile.role))}</p><button class="primary">Save details</button></form><form id="support-form" class="card stack"><h2>Ask for help</h2><label>Subject<input class="field" name="subject" required></label><label>Order reference (optional)<input class="field" name="orderId"></label><label>Message<textarea name="message" required></textarea></label><button class="primary">Send support request</button></form><form id="deletion-form" class="card stack"><h2>Request account deletion review</h2><p class="meta">This records a review request. It does not silently erase financial records.</p><label>Reason<textarea name="reason" required></textarea></label><button class="danger">Request review</button></form></div><h2>Support cases</h2>${support.length ? `<div class="grid">${support.map((x) => `<article class="card"><span class="badge">${e(x.status)}</span><h3>${e(x.subject)}</h3><p>${e(x.message)}</p><p class="meta">${date(x.createdAt)}</p></article>`).join("")}</div>` : `<div class="empty">No support cases.</div>`}<h2>Deletion requests</h2>${deletion.length ? `<div class="grid">${deletion.map((x) => `<article class="card"><span class="badge">${e(statusLabel(x.status))}</span><p>${e(x.reason)}</p><p class="meta">${date(x.createdAt)}</p></article>`).join("")}</div>` : `<div class="empty">No deletion review requests.</div>`}</section>`;
}

async function loadOrders(polling = false) {
  const generation = state.generation; if (!polling) loading("Loading your orders");
  try { const orders = await api("/api/orders"); if (generation !== state.generation || state.view !== "orders") return; state.orders = orders; if (!polling) renderOrders(); else updateOrderCards(); if (!state.poll) state.poll = setInterval(() => loadOrders(true), 5000); }
  catch (error) { if (!polling) showError(error, "reload-orders"); }
}

function orderCard(order) {
  const flow = ORDER_FLOW[order.fulfillment] ?? ORDER_FLOW.collection; const current = flow.indexOf(order.status);
  return `<article class="card order-card" data-order-id="${e(order.id)}"><div class="order-top"><div><span class="badge">${e(statusLabel(order.status))}</span><h3>${e(order.restaurantName)}</h3><span class="meta">${e(shortId(order.id))} · ${date(order.createdAt)}</span></div><strong>${money(order.totalMinor)}</strong></div><div class="timeline" aria-label="Order progress">${flow.map((step, index) => `<span class="timeline-step ${index <= current ? "done" : ""}">${e(statusLabel(step))}</span>`).join("")}</div><p class="meta">${order.items.map((item) => `${item.quantity} × ${e(item.name)}`).join(" · ")}</p><p class="meta">${e(statusLabel(order.paymentStatus))} · ${e(statusLabel(order.fulfillment))}</p><div class="card-actions"><button class="secondary" data-action="print-receipt" data-id="${e(order.id)}">Print receipt</button><button class="secondary" data-action="reorder" data-id="${e(order.id)}">Reorder with current prices</button></div></article>`;
}
function renderOrders() { main.innerHTML = `<section class="section"><div class="section-head"><div><div class="eyebrow">Updates every 5 seconds</div><h1>Your orders</h1></div></div><div id="orders-list" class="grid">${state.orders.length ? state.orders.map(orderCard).join("") : `<div class="empty">No orders yet. Your first local meal can start from Find food.</div>`}</div></section>`; }
function updateOrderCards() { const list = document.querySelector("#orders-list"); if (list) list.innerHTML = state.orders.length ? state.orders.map(orderCard).join("") : `<div class="empty">No orders yet.</div>`; }
async function reorder(id) { const order = state.orders.find((item) => item.id === id); if (!order) return; await openMenu(order.restaurantId); let needsChoices = false; for (const prior of order.items.filter((item) => !item.isOfferItem)) { const fresh = state.menu.find((item) => item.id === prior.menuItemId); if (fresh) { state.cart[fresh.id] = prior.quantity; state.modifiers[fresh.id] = currentSelections(fresh, prior.selectedModifiers ?? []); if (!validateModifierSelection(fresh, state.modifiers[fresh.id]).ok) needsChoices = true; } } state.fulfillment = order.fulfillment; state.fulfillmentExplicit = true; renderMenu(); message(needsChoices ? "Basket updated. Choose the current required options before checkout." : "Basket rebuilt with current paid items and available choices."); }

function renderDenied(text) { stopOrderPolling(); main.innerHTML = `<section class="section"><div class="error"><strong>That area isn’t available to this account.</strong><br>${e(text)}</div><button class="primary" data-view="discover">Back to food</button></section>`; }

async function loadWorkspace() {
  stopOrderPolling(); if (state.user.role === "customer") return renderDenied("Restaurant and admin workspaces require the matching role.");
  loading("Opening workspace"); const generation = state.generation;
  try { if (state.user.role === "restaurant") await loadRestaurantWorkspace(generation); else if (state.user.role === "admin") await loadAdminWorkspace(generation); else renderDenied("Unknown account role."); } catch (error) { if (generation === state.generation) showError(error, "reload-workspace"); }
}

async function loadRestaurantWorkspace(generation) {
  const restaurants = await api("/api/restaurant/restaurants"); state.workspace.restaurants = restaurants;
  if (generation !== state.generation || state.view !== "workspace") return;
  if (!restaurants.length) return renderRestaurantApplication();
  const restaurant = restaurants[0]; state.workspace.restaurant = restaurant;
  const [menu, orders, contract, statement, staff, customers, campaigns] = await Promise.allSettled([api(`/api/restaurant/restaurants/${restaurant.id}/menu`), api(`/api/restaurant/restaurants/${restaurant.id}/orders`), api(`/api/restaurant/restaurants/${restaurant.id}/contract`), api(`/api/restaurant/restaurants/${restaurant.id}/statement`), api(`/api/restaurant/restaurants/${restaurant.id}/staff`), api(`/api/restaurant/restaurants/${restaurant.id}/customers`), api(`/api/restaurant/restaurants/${restaurant.id}/offers`)]);
  if (generation !== state.generation || state.view !== "workspace") return;
  state.workspace.menu = menu.status === "fulfilled" ? menu.value.items : []; state.workspace.orders = orders.status === "fulfilled" ? orders.value : []; state.workspace.contract = contract.status === "fulfilled" ? contract.value : null; state.workspace.statement = statement.status === "fulfilled" ? statement.value : null; state.workspace.staff = staff.status === "fulfilled" ? staff.value : null; state.workspace.customers = customers.status === "fulfilled" ? customers.value : []; state.workspace.campaigns = campaigns.status === "fulfilled" ? campaigns.value : []; state.workspace.isOwner = staff.status === "fulfilled"; renderRestaurantWorkspace();
}
function renderRestaurantApplication() { main.innerHTML = `<section class="section"><div class="eyebrow">Restaurant partner</div><h1>Apply to join Calai Eats</h1><form id="restaurant-create" class="card stack"><label>Restaurant name<input class="field" name="name" required maxlength="100"></label><p class="notice">Applications begin in pending review. Creating this local demo record does not activate a live commercial agreement.</p><button class="primary">Send application</button></form></section>`; }
function renderRestaurantWorkspace() {
  const r = state.workspace.restaurant; const items = state.workspace.menu; const orders = state.workspace.orders; const contract = state.workspace.contract; const statement = state.workspace.statement; const owner = state.workspace.isOwner;
  main.innerHTML = `<section class="section"><div class="section-head"><div><div class="eyebrow">Restaurant workspace · ${owner ? "Owner" : "Staff"}</div><h1>${e(r.name)}</h1></div><span class="badge ${e(r.status)}">${e(r.status)}</span></div>${r.status === "pending" ? `<div class="notice">Your application is waiting for admin review.</div>` : r.status === "rejected" ? `<div class="error">This application was not approved. Ordering remains unavailable.</div>` : ""}<div class="connection"><span class="connection-dot"></span> Local API connected · refreshed ${e(new Date().toLocaleTimeString("en-GB"))} <button class="quiet" data-action="test-notification">Test local notification</button></div><div class="tabs" role="tablist"><button aria-selected="true" data-worktab="orders">Orders</button>${owner ? `<button data-worktab="offers">Customers & offers</button><button data-worktab="menu">Menu</button><button data-worktab="delivery">Delivery</button><button data-worktab="profile">Profile & hours</button><button data-worktab="staff">Staff</button><button data-worktab="finance">Terms & statement</button>` : ""}</div><div id="workpanel">${restaurantOrdersHtml(orders)}</div></section>`;
  document.querySelector('[data-action="test-notification"]')?.remove();
  labelFreeOfferItems(document.querySelector("#workpanel"), orders);
  state.workspace.panels = { orders: () => restaurantOrdersHtml(state.workspace.orders), offers: () => merchantOffersHtml(state.workspace.customers, state.workspace.campaigns, items), menu: () => restaurantMenuHtml(items), delivery: () => deliveryHtml(r), profile: () => restaurantProfileHtml(r), staff: () => staffHtml(state.workspace.staff ?? []), finance: () => financeHtml(contract, statement) };
  state.poll = setInterval(refreshRestaurantOrders, 5000);
}
function labelFreeOfferItems(panel, orders) { if (!panel) return; panel.querySelectorAll("article.card").forEach((card,index)=>{const free=orders[index]?.items?.filter((item)=>item.isOfferItem)??[];if(!free.length)return;const note=document.createElement("p");note.className="offer-kitchen-note";note.textContent=`Free offer: ${free.map((item)=>`${item.quantity} × ${item.name}`).join(", ")}`;card.append(note);}); }
async function refreshRestaurantOrders() { const selected = document.querySelector('[data-worktab="orders"][aria-selected="true"]'); const panel = document.querySelector("#workpanel"); if (!selected || !panel || state.view !== "workspace") return; const generation=state.generation; try { const orders=await api(`/api/restaurant/restaurants/${state.workspace.restaurant.id}/orders`); if(generation!==state.generation || !document.querySelector('[data-worktab="orders"][aria-selected="true"]')) return; state.workspace.orders=orders; panel.innerHTML=restaurantOrdersHtml(orders); labelFreeOfferItems(panel,orders); } catch { /* notification inbox still exposes actionable failures */ } }
function merchantOffersHtml(customers, campaigns, items) { const eligibleItems = items.filter((item) => item.available && !(item.modifierGroups ?? []).some((group) => group.minSelections > 0)); return `<div><h2>Customers & tailored offers</h2><div class="notice">Offers are funded by this restaurant and delivered only in the local app. A normal paid item is required.</div><form id="offer-form" class="card form-grid"><fieldset class="full"><legend>Recipients</legend>${customers.map((c) => `<label class="customer-choice"><input type="checkbox" name="customerIds" value="${e(c.customerId)}"><span><strong>${e(c.name)}</strong> · ${c.completedOrderCount} completed · ${money(c.netSpendMinor)} net spend · last ${date(c.lastOrderAt)}</span></label>`).join("") || `<p class="muted">No eligible completed-order customers.</p>`}</fieldset><label>Free item<select name="menuItemId" required>${eligibleItems.map((i) => `<option value="${e(i.id)}">${e(i.name)} · value ${money(i.priceMinor)}</option>`).join("")}</select></label><label>Paid food minimum (£)<input name="minimum" type="number" min="0" max="1000" step="0.01" value="10"></label><label>Expires in days<input name="expiresInDays" type="number" min="1" max="90" value="14" required></label><label>Title<input name="title" maxlength="80" required></label><label class="full">Message<textarea name="message" maxlength="500" required></textarea></label><button class="primary" ${customers.length && eligibleItems.length ? "" : "disabled"}>Send in-app offer</button><div class="form-error full"></div></form><h2>Campaign analytics</h2><div class="grid section-gap">${campaigns.map((c) => `<article class="card"><h3>${e(c.title)}</h3><p>Free ${e(c.itemName)} · ${money(c.minSubtotalMinor)} minimum</p><div class="campaign-metrics"><span>${c.recipientCount}<small>Recipients</small></span><span>${c.openedCount}<small>Opened</small></span><span>${c.reservedCount}<small>Reserved</small></span><span>${c.redeemedCount}<small>Redeemed</small></span></div><p class="meta">Expires ${date(c.expiresAt)}</p></article>`).join("") || `<div class="empty">No campaigns sent yet.</div>`}</div></div>`; }
function restaurantOrdersHtml(orders) { return `<div><h2>Live orders</h2>${orders.length ? `<div class="grid">${orders.map((o) => `<article class="card"><div class="order-top"><div><span class="badge">${e(statusLabel(o.status))}</span><h3>${e(shortId(o.id))}</h3></div><strong>${money(o.totalMinor)}</strong></div>${o.allergyNotes ? `<div class="allergy-note"><strong>Allergy note</strong><p>${e(o.allergyNotes)}</p></div>` : ""}${o.customerName ? `<p><strong>${e(o.customerName)}</strong> · ${e(o.customerPhone || "No phone supplied")}</p>` : ""}${o.deliveryInstructions ? `<p><strong>Delivery instructions:</strong> ${e(o.deliveryInstructions)}</p>` : ""}<p>${o.items.map((i) => `${i.quantity} × ${e(i.name)}${i.selectedModifiers?.length ? ` (${i.selectedModifiers.map((m) => e(m.name)).join(", ")})` : ""}`).join(" · ")}</p><p class="meta">${e(statusLabel(o.paymentStatus))} · ${e(statusLabel(o.fulfillment))}</p><div class="card-actions">${nextOrderStatuses(o).map((next) => `<button class="${next === "rejected" ? "danger" : "primary"}" data-action="order-status" data-id="${e(o.id)}" data-status="${e(next)}">${next === "completed" && o.paymentMethod === "cash" ? "Confirm complete & cash collected" : e(statusLabel(next))}</button>`).join("")}<a class="secondary" href="/api/orders/${encodeURIComponent(o.id)}/receipt" target="_blank" rel="noopener">Receipt</a></div></article>`).join("")}</div>` : `<div class="empty">No orders yet.</div>`}</div>`; }
function restaurantMenuHtml(items) { return `<div><h2>Menu</h2><form id="menu-create" class="card form-grid"><label>Item name<input class="field" name="name" required></label><label>Price (£)<input class="field" name="price" type="number" min="0" step="0.01" required></label><label>Category<input class="field" name="category" required placeholder="Mains"></label><label>Allergens, comma separated<input class="field" name="allergens" placeholder="milk, sesame"></label><label>Dietary tags, comma separated<input class="field" name="dietaryTags" placeholder="vegan, halal"></label><label class="full">Description<textarea name="description"></textarea></label><label class="full">Modifier groups (validated JSON)<textarea class="code-field" name="modifierGroups" placeholder='[{"id":"size","name":"Size","minSelections":1,"maxSelections":1,"options":[{"id":"large","name":"Large","priceMinor":200,"available":true}]}]'>[]</textarea></label><p class="meta full">Extra prices are in pounds. Required groups need enough available choices.</p><button class="primary">Add item</button></form><div class="grid section-gap">${items.map((i) => `<article class="card"><span class="badge">${e(i.category || "Menu")}</span><h3>${e(i.name)}</h3><p>${e(i.description)}</p><p class="meta">Allergens: ${e(i.allergens?.join(", ") || "none listed")} · ${e(i.modifierGroups?.length ?? 0)} modifier group(s)</p><strong>${money(i.priceMinor)}</strong><div class="card-actions"><button class="secondary" data-action="toggle-item" data-id="${e(i.id)}" data-available="${!i.available}">${i.available ? "Mark unavailable" : "Make available"}</button><button class="secondary" data-action="edit-item-json" data-id="${e(i.id)}">Edit item</button></div></article>`).join("")}</div></div>`; }
function deliveryHtml(r) { const d = r.delivery; return `<div><h2>Delivery setup</h2><form id="delivery-form" class="card form-grid"><label class="radio-card"><input type="checkbox" name="enabled" ${d.enabled ? "checked" : ""}> Offer delivery</label><label>Outcodes, comma separated<input class="field" name="outcodes" value="${e(d.outcodes.join(", "))}" placeholder="LU1, LU2"></label><label>Delivery fee (£)<input class="field" name="fee" type="number" min="0" step="0.01" value="${(d.deliveryFeeMinor / 100).toFixed(2)}"></label><label>Minimum food order (£)<input class="field" name="minimum" type="number" min="0" step="0.01" value="${(d.minDeliverySubtotalMinor / 100).toFixed(2)}"></label><button class="primary">Save delivery settings</button></form></div>`; }
function restaurantProfileHtml(r) { const p = r.profile ?? {}; return `<div><h2>Profile, availability & hours</h2><form id="profile-form" class="card form-grid"><label>Restaurant name<input class="field" name="name" value="${e(r.name)}" required></label><label>Cuisine<input class="field" name="cuisine" value="${e(p.cuisine || "")}" required></label><label class="full">Description<textarea name="description">${e(p.description || "")}</textarea></label><label>Business phone<input class="field" name="phone" type="tel" value="${e(p.phone || "")}"></label><label>Address<input class="field" name="address" value="${e(p.address || "")}"></label><label>Delivery estimate (minutes)<input class="field" name="estimatedDeliveryMinutes" type="number" min="0" value="${e(p.estimatedDeliveryMinutes ?? 30)}"></label><label>Collection estimate (minutes)<input class="field" name="estimatedCollectionMinutes" type="number" min="0" value="${e(p.estimatedCollectionMinutes ?? 15)}"></label><label>Busy delay (minutes)<input class="field" name="busyMinutes" type="number" min="0" value="${e(p.busyMinutes ?? 0)}"></label><label>Holiday dates, comma separated<input class="field" name="holidayDates" value="${e((p.holidayDates ?? []).join(", "))}" placeholder="2026-12-25"></label><label class="full">Opening hours (validated JSON)<textarea class="code-field" name="openingHours">${e(JSON.stringify(p.openingHours ?? [], null, 2))}</textarea></label><div class="full radio-row"><label class="radio-card"><input type="checkbox" name="collectionEnabled" ${p.collectionEnabled ? "checked" : ""}> Collection</label><label class="radio-card"><input type="checkbox" name="cashEnabled" ${p.cashEnabled ? "checked" : ""}> Cash</label><label class="radio-card"><input type="checkbox" name="paused" ${p.paused ? "checked" : ""}> Pause new orders</label><label class="radio-card"><input type="checkbox" name="alwaysOpen" ${p.alwaysOpen ? "checked" : ""}> Always open demo fixture</label></div><button class="primary">Save profile</button></form></div>`; }
function staffHtml(rows) { return `<div><h2>Staff access</h2><div class="notice">Staff can view and progress this restaurant’s orders. They cannot change settings, menu, staff or finance.</div><form id="staff-form" class="card form-grid"><label>Name<input class="field" name="name" required></label><label>Email<input class="field" name="email" type="email" required></label><label>Password<input class="field" name="password" type="password" minlength="12" required></label><button class="primary">Add staff member</button></form><div class="grid section-gap">${rows.map((x) => `<article class="card"><span class="badge">${e(x.permission)}</span><h3>${e(x.name)}</h3><p>${e(x.email)}</p></article>`).join("")}</div></div>`; }
const dayNames=["Sunday","Monday","Tuesday","Wednesday","Thursday","Friday","Saturday"];
function hourRow(row={day:1,open:"09:00",close:"17:00"}) { return `<div class="editor-row hours-row"><label>Day<select class="hour-day">${dayNames.map((name,index)=>`<option value="${index}" ${Number(row.day)===index?"selected":""}>${name}</option>`).join("")}</select></label><label>Opens<input class="hour-open" type="time" value="${e(row.open)}" required></label><label>Closes<input class="hour-close" type="time" value="${e(row.close)}" required></label><button type="button" class="danger" data-action="remove-editor-row">Remove</button></div>`; }
function enhanceHours(form) { const textarea=form?.querySelector('textarea[name="openingHours"]');if(!textarea)return;let rows=[];try{rows=JSON.parse(textarea.value)||[];}catch{}const editor=document.createElement("div");editor.className="full simple-editor hours-editor";editor.innerHTML=`<div class="editor-heading"><strong>Opening hours</strong><button type="button" class="secondary" data-action="add-hour-row">Add hours</button></div><p class="meta">Add more than one row for split service. Closing earlier than opening means overnight.</p><div class="editor-rows">${rows.map(hourRow).join("")}</div>`;textarea.closest("label").replaceWith(editor); }
function optionRow(option={id:"",name:"",priceMinor:0,available:true}) { return `<div class="editor-row option-row"><input class="option-id" type="hidden" value="${e(option.id)}"><label>Option name<input class="option-name" value="${e(option.name)}" required></label><label>Extra (£)<input class="option-price" type="number" min="0" step="0.01" value="${(Number(option.priceMinor||0)/100).toFixed(2)}" required></label><label class="radio-card"><input class="option-available" type="checkbox" ${option.available!==false?"checked":""}> Available</label><button type="button" class="danger" data-action="remove-editor-row">Remove</button></div>`; }
function modifierGroup(group={id:"",name:"",minSelections:0,maxSelections:1,options:[]}) { return `<fieldset class="modifier-editor-group"><legend>Choice group</legend><input class="group-id" type="hidden" value="${e(group.id)}"><div class="editor-row"><label>Group name<input class="group-name" value="${e(group.name)}" required></label><label>Minimum<input class="group-min" type="number" min="0" value="${e(group.minSelections)}" required></label><label>Maximum<input class="group-max" type="number" min="0" value="${e(group.maxSelections)}" required></label><button type="button" class="danger" data-action="remove-editor-group">Remove group</button></div><div class="option-rows">${group.options.map(optionRow).join("")}</div><button type="button" class="secondary" data-action="add-option-row">Add option</button></fieldset>`; }
function enhanceModifiers(form) { const textarea=form?.querySelector('textarea[name="modifierGroups"]');if(!textarea)return;let groups=[];try{groups=JSON.parse(textarea.value)||[];}catch{}const editor=document.createElement("div");editor.className="full simple-editor modifier-editor";editor.innerHTML=`<div class="editor-heading"><strong>Choices and extras</strong><button type="button" class="secondary" data-action="add-modifier-group">Add choice group</button></div><p class="meta">For optional choices use minimum 0. For a required choice use minimum 1.</p><div class="modifier-groups">${groups.map(modifierGroup).join("")}</div>`;textarea.closest("label").replaceWith(editor); }
function readHours(form){return serializeOpeningRows([...form.querySelectorAll(".hours-row")].map((row)=>({day:row.querySelector(".hour-day").value,open:row.querySelector(".hour-open").value,close:row.querySelector(".hour-close").value})));}
function readModifiers(form){return serializeModifierRows([...form.querySelectorAll(".modifier-editor-group")].map((group)=>({id:group.querySelector(".group-id").value,name:group.querySelector(".group-name").value,minSelections:group.querySelector(".group-min").value,maxSelections:group.querySelector(".group-max").value,options:[...group.querySelectorAll(".option-row")].map((option)=>({id:option.querySelector(".option-id").value,name:option.querySelector(".option-name").value,extraPrice:option.querySelector(".option-price").value,available:option.querySelector(".option-available").checked}))})));}
function financeHtml(contract, statement) { return `<div><h2>Development terms</h2>${contract ? `<div class="card"><span class="badge">Demo only</span><h3>${contract.rateBasisPoints / 100}% commission for ${contract.durationMonths} months</h3><p>Policy ${e(contract.policyVersion)}. This seeded local record is not a live legal agreement or activation.</p></div>` : `<div class="notice">No demo contract record is available.</div>`}<h2>Statement</h2>${statement ? `<div class="kpis"><div class="card kpi">Mock-card commission<strong>${money(statement.commissionMockMinor)}</strong></div><div class="card kpi">Cash receivable<strong>${money(statement.cashReceivableMinor)}</strong></div><div class="card kpi">Cash settled<strong>${money(statement.cashSettledMinor)}</strong></div><div class="card kpi">Outstanding / credit<strong>${money(statement.cashOutstandingMinor)}</strong></div></div>` : `<div class="notice">Statement endpoint is not available in this local API yet.</div>`}</div>`; }

async function loadAdminWorkspace(generation) {
  const paths = { restaurants: "/api/admin/restaurants", orders: "/api/admin/orders", ledger: "/api/admin/ledger", contracts: "/api/admin/contracts", statements: "/api/admin/statements", audit: "/api/admin/audit", jobs: "/api/admin/jobs", integrations: "/api/admin/integrations", support: "/api/admin/support", deletion: "/api/admin/deletion-requests" };
  const entries = await Promise.all(Object.entries(paths).map(async ([key, path]) => { try { return [key, await api(path)]; } catch { return [key, null]; } })); if (generation !== state.generation || state.view !== "workspace") return; state.workspace = Object.fromEntries(entries); renderAdminWorkspace();
}
function renderAdminWorkspace() {
  const w = state.workspace; const orders = w.orders ?? []; const ledger = w.ledger ?? [];
  const cashOutstanding = w.statements?.reduce((sum, s) => sum + s.cashOutstandingMinor, 0) ?? ledger.filter((x) => x.kind === "commission_cash_receivable" || x.kind === "commission_cash_refund").reduce((s,x) => s+x.amountMinor,0) - ledger.filter((x) => x.kind === "cash_settlement").reduce((s,x) => s+x.amountMinor,0);
  main.innerHTML = `<section class="section"><div class="section-head"><div><div class="eyebrow">Local operations</div><h1>Admin workspace</h1></div><span class="badge">Development only</span></div><div class="kpis"><div class="card kpi">Restaurants<strong>${w.restaurants?.length ?? "—"}</strong></div><div class="card kpi">Orders<strong>${orders.length}</strong></div><div class="card kpi">Mock commission<strong>${money(ledger.filter((x) => x.kind === "commission_mock" || x.kind === "commission_mock_refund").reduce((s,x) => s+x.amountMinor,0))}</strong></div><div class="card kpi">Cash outstanding / credit<strong>${money(cashOutstanding)}</strong></div></div><div class="tabs" role="tablist"><button aria-selected="true" data-admintab="restaurants">Approvals</button><button data-admintab="orders">Orders</button><button data-admintab="ledger">Ledger</button><button data-admintab="cases">Support & deletion</button><button data-admintab="margin">Margin estimate</button><button data-admintab="operations">Operations</button></div><div id="adminpanel">${adminRestaurants(w.restaurants ?? [])}</div></section>`;
  state.workspace.adminPanels = { restaurants: () => adminRestaurants(w.restaurants ?? []), orders: () => adminOrders(orders), ledger: () => adminLedger(ledger, w.statements), cases: () => adminCases(w.support ?? [], w.deletion ?? []), margin: () => marginHtml(ledger), operations: () => adminOperations(w) };
}
function adminRestaurants(rows) { return `<div><h2>Restaurant approvals & cash settlements</h2><div class="grid">${rows.map((r) => `<article class="card"><span class="badge ${e(r.status)}">${e(r.status)}</span>${r.suspended ? `<span class="badge rejected">Suspended</span>` : ""}<h3>${e(r.name)}</h3><p class="meta">Created ${date(r.createdAt)}</p><div class="card-actions"><button class="primary" data-action="approval" data-id="${e(r.id)}" data-status="approved">Approve</button><button class="danger" data-action="approval" data-id="${e(r.id)}" data-status="rejected">Reject</button><button class="secondary" data-action="settlement-dialog" data-id="${e(r.id)}">Record cash settlement</button><button class="${r.suspended ? "secondary" : "danger"}" data-action="suspension-dialog" data-id="${e(r.id)}" data-suspended="${!r.suspended}">${r.suspended ? "Lift suspension" : "Suspend"}</button></div></article>`).join("") || `<div class="empty">No restaurant applications.</div>`}</div></div>`; }
function adminOrders(rows) { return `<div><div class="section-head"><h2>All orders</h2><label>Search<input id="admin-order-search" class="field" type="search" placeholder="Order or restaurant"></label></div><div id="admin-orders" class="grid">${rows.map(adminOrderCard).join("") || `<div class="empty">No orders.</div>`}</div></div>`; }
function adminOrderCard(o) { return `<article class="card"><span class="badge">${e(statusLabel(o.status))}</span><h3>${e(o.restaurantName)}</h3><p>${e(shortId(o.id))} · ${money(o.totalMinor)}</p><p class="meta">${e(statusLabel(o.paymentStatus))} · refunded ${money(o.refundedTotalMinor ?? 0)}</p><div class="card-actions"><button class="secondary" data-action="order-detail" data-id="${e(o.id)}">Details & refund</button><a class="secondary" href="/api/orders/${encodeURIComponent(o.id)}/receipt" target="_blank" rel="noopener">Receipt</a></div></article>`; }
function adminLedger(rows, statements) { return `<div><h2>Ledger</h2><div class="notice">Mock-card commission and cash receivables are shown separately. Cash receivable is not platform income.</div><div class="table-wrap"><table class="data-table"><thead><tr><th>When</th><th>Order</th><th>Kind</th><th>Amount</th></tr></thead><tbody>${rows.map((x) => `<tr><td>${date(x.createdAt)}</td><td>${e(shortId(x.orderId))}</td><td>${e(statusLabel(x.kind))}</td><td>${money(x.amountMinor)}</td></tr>`).join("")}</tbody></table></div>${statements ? `<p class="meta">${statements.length} restaurant statement(s) available.</p>` : ""}<div class="card-actions"><a class="secondary" href="/api/admin/reports/ledger.csv">Export ledger CSV</a><a class="secondary" href="/api/admin/reports/orders.csv">Export orders CSV</a></div></div>`; }
function adminOperations(w) { const integrations=Array.isArray(w.integrations)?w.integrations:[]; return `<div><h2>Integrations</h2><div class="grid">${integrations.length?integrations.map((item)=>`<article class="card integration-card"><span class="badge ${item.enabled?"":"pending"}">${item.enabled?"Enabled":"Off"}</span><h3>${e(item.name)}</h3><p>${e(item.detail)}</p><p class="meta">Mode: ${e(statusLabel(item.mode))}</p></article>`).join(""):`<div class="empty">No integrations configured. Live payments remain disabled.</div>`}</div><h2>Local operations</h2><div class="grid"><section class="card"><h3>Jobs</h3><p>${w.jobs?.length?`${w.jobs.length} persisted job record(s).`:"No job records."}</p></section><section class="card"><h3>Audit</h3><p>${w.audit?.length?`${w.audit.length} persisted audit event(s).`:"No audit events."}</p></section><section class="card"><h3>Contracts</h3><p>${w.contracts?.length?`${w.contracts.length} demo contract record(s).`:"No contract records."}</p></section></div></div>`; }
function adminCases(support, deletion) { return `<div><h2>Support</h2><div class="grid">${support.map((x) => `<article class="card"><span class="badge">${e(x.status)}</span><h3>${e(x.subject)}</h3><p>${e(x.message)}</p><button class="secondary" data-action="support-status" data-id="${e(x.id)}" data-status="${x.status === "resolved" ? "open" : "resolved"}">Mark ${x.status === "resolved" ? "open" : "resolved"}</button></article>`).join("") || `<div class="empty">No support cases.</div>`}</div><h2>Deletion reviews</h2><div class="grid">${deletion.map((x) => `<article class="card"><span class="badge">${e(statusLabel(x.status))}</span><p>${e(x.reason)}</p><button class="secondary" data-action="deletion-dialog" data-id="${e(x.id)}">Update review</button></article>`).join("") || `<div class="empty">No deletion requests.</div>`}</div></div>`; }
function marginHtml(ledger) { const gross = recognisedCommission(ledger); return `<div><h2>Estimated margin calculator</h2><div class="notice">An estimate using only costs you enter. Recognised commission after refund adjustments is not net profit, and no provider prices are assumed.</div><form id="margin-form" class="card form-grid" data-gross="${gross}"><div class="kpi">Recognised commission<strong>${money(gross)}</strong></div>${["Processing","Connect","Payout","Refund","Other"].map((label) => `<label>${label} costs (£)<input class="field margin-cost" type="number" min="0" step="0.01" value="0"></label>`).join("")}<div class="kpi full">Estimated margin<strong id="margin-result">${money(gross)}</strong></div></form></div>`; }

async function mutate(path, method, body, headers) { const generation = state.generation; try { await api(path, { method, body: JSON.stringify(body), headers }); if (generation !== state.generation) return; message("Saved."); await loadWorkspace(); } catch (error) { if (generation === state.generation) message(error.message); } }
function showDialog(content) { state.dialogReturnFocus = document.activeElement; document.body.insertAdjacentHTML("beforeend", `<div class="dialog-backdrop" data-action="close-dialog"><div class="dialog" role="dialog" aria-modal="true" aria-labelledby="dialog-title" data-dialog>${content}<button class="quiet" data-action="close-dialog">Close</button></div></div>`); enhanceModifiers(document.querySelector("#menu-edit")); document.querySelector("#dialog-title")?.focus(); }
function closeDialog() { document.querySelector(".dialog-backdrop")?.remove(); state.dialogReturnFocus?.focus?.(); }
function showOrderDetail(order) { showDialog(`<h2 id="dialog-title" tabindex="-1">Order ${e(shortId(order.id))}</h2><p>${order.items.map((i) => `${i.quantity} × ${e(i.name)}`).join(" · ")}</p><p>Food ${money(order.subtotalMinor)} · delivery ${money(order.deliveryFeeMinor)} · total ${money(order.totalMinor)}</p><h3>Simulated refund</h3><form id="refund-form" class="stack" data-id="${e(order.id)}"><label>Food amount (£)<input class="field" name="food" type="number" min="0" step="0.01" value="0"></label><label>Delivery amount (£)<input class="field" name="delivery" type="number" min="0" step="0.01" value="0"></label><label>Reason<input class="field" name="reason" required></label><button class="primary">Record refund</button><div class="form-error"></div></form>`); }
function showSettlement(id) { showDialog(`<h2 id="dialog-title" tabindex="-1">Record cash settlement</h2><p class="notice">Records a manual settlement only. No bank call or direct debit occurs.</p><form id="settlement-form" class="stack" data-id="${e(id)}"><label>Amount (£)<input class="field" name="amount" type="number" min="0.01" step="0.01" required></label><label>Reference<input class="field" name="reference" required></label><button class="primary">Record settlement</button><div class="form-error"></div></form>`); }
function showSuspension(id, suspended) { showDialog(`<h2 id="dialog-title" tabindex="-1">${suspended ? "Suspend restaurant" : "Lift suspension"}</h2><form id="suspension-form" class="stack" data-id="${e(id)}" data-suspended="${suspended}"><label>Reason<input class="field" name="reason" required></label><button class="${suspended ? "danger" : "primary"}">Confirm</button></form>`); }
function showDeletionReview(id) { showDialog(`<h2 id="dialog-title" tabindex="-1">Update deletion review</h2><form id="deletion-review-form" class="stack" data-id="${e(id)}"><label>Status<select name="status"><option value="under_review">Under review</option><option value="resolved">Resolved</option></select></label><label>Review note<textarea name="note" required></textarea></label><p class="meta">Resolved records administrative review; it does not claim erasure.</p><button class="primary">Save review</button></form>`); }
async function printReceipt(id) {
  const popup = window.open("", "_blank");
  try { const job = await api(`/api/orders/${encodeURIComponent(id)}/print-jobs`, { method: "POST", body: "{}" }); if (popup) { popup.location = job.receiptUrl; await api(`/api/print-jobs/${encodeURIComponent(job.id)}`, { method: "PATCH", body: JSON.stringify({ status: "browser_opened" }) }); } else { await api(`/api/print-jobs/${encodeURIComponent(job.id)}`, { method: "PATCH", body: JSON.stringify({ status: "failed", error: "Browser blocked the receipt window" }) }); message("Allow pop-ups to open the receipt."); } } catch (error) { popup?.close(); window.open(`/api/orders/${encodeURIComponent(id)}/receipt`, "_blank", "noopener"); message(`Print tracking unavailable: ${error.message}`); }
}

document.addEventListener("click", async (event) => {
  const button = event.target.closest("button,[data-view]"); if (!button) return;
  if (button.dataset.view) return navigate(button.dataset.view);
  const action = button.dataset.action;
  if (action === "home" || action === "back-discover" || action === "reload-discover") return navigate("discover");
  if (action === "remove-editor-row") { button.closest(".editor-row")?.remove(); return; }
  if (action === "remove-editor-group") { button.closest(".modifier-editor-group")?.remove(); return; }
  if (action === "add-hour-row") { button.closest(".hours-editor").querySelector(".editor-rows").insertAdjacentHTML("beforeend",hourRow()); return; }
  if (action === "add-modifier-group") { button.closest(".modifier-editor").querySelector(".modifier-groups").insertAdjacentHTML("beforeend",modifierGroup()); return; }
  if (action === "add-option-row") { button.closest(".modifier-editor-group").querySelector(".option-rows").insertAdjacentHTML("beforeend",optionRow()); return; }
  if (action === "auth") return renderAuth();
  if (action === "notifications") return showNotifications();
  if (action === "mark-notification") { await api(`/api/notifications/${button.dataset.id}`, { method:"PATCH", body:JSON.stringify({read:true}) }).catch((error)=>message(error.message)); await loadNotifications(); closeDialog(); return showNotifications(); }
  if (action === "notification-order") { await api(`/api/notifications/${button.dataset.id}`, { method:"PATCH", body:JSON.stringify({read:true}) }).catch(()=>{}); closeDialog(); return state.user.role === "customer" ? navigate("orders") : navigate("workspace"); }
  if (action === "notification-offer") { await api(`/api/notifications/${button.dataset.id}`, { method:"PATCH", body:JSON.stringify({read:true}) }).catch(()=>{}); const offerId=button.dataset.offer; closeDialog(); state.view="offers"; loading("Opening offer"); try { state.offers=await api("/api/offers"); if(state.offers.some((offer)=>offer.id===offerId)) await api(`/api/offers/${encodeURIComponent(offerId)}`,{method:"PATCH",body:JSON.stringify({viewed:true})}); renderOffers(); await loadNotifications(); } catch(error){showError(error);} return; }
  if (action === "logout") { try { await api("/api/auth/logout", { method: "POST", body: "{}" }); } finally { resetIdentity(null); navigate("discover"); } return; }
  if (button.dataset.demo) return demoLogin(button.dataset.demo);
  if (action === "clear-filters") { state.postcode = ""; state.search = ""; renderDiscover(); return; }
  if (action === "quick-fulfillment") { state.fulfillment = button.dataset.value; state.fulfillmentExplicit = true; return loadDiscover(); }
  if (action === "cuisine-chip") { state.cuisine = button.dataset.value; return loadDiscover(); }
  if (action === "open-menu") return openMenu(button.dataset.id);
  if (action === "qty") { state.cart[button.dataset.id] = Math.max(0, (state.cart[button.dataset.id] ?? 0) + Number(button.dataset.delta)); return renderMenu(); }
  if (action === "checkout") return renderCheckout();
  if (action === "back-menu") return renderMenu();
  if (action === "reload-orders") return loadOrders();
  if (action === "reload-workspace") return loadWorkspace();
  if (action === "reorder") return reorder(button.dataset.id);
  if (action === "choose-offer") return chooseOffer(button.dataset.id);
  if (action === "print-receipt") return printReceipt(button.dataset.id);
  if (button.dataset.worktab) { document.querySelectorAll("[data-worktab]").forEach((n) => n.setAttribute("aria-selected", n === button)); const panel=document.querySelector("#workpanel");panel.innerHTML = state.workspace.panels[button.dataset.worktab]();if(button.dataset.worktab==="orders")labelFreeOfferItems(panel,state.workspace.orders);if(button.dataset.worktab==="menu")enhanceModifiers(panel.querySelector("#menu-create"));if(button.dataset.worktab==="profile")enhanceHours(panel.querySelector("#profile-form")); return; }
  if (button.dataset.admintab) { document.querySelectorAll("[data-admintab]").forEach((n) => n.setAttribute("aria-selected", n === button)); document.querySelector("#adminpanel").innerHTML = state.workspace.adminPanels[button.dataset.admintab](); return; }
  if (action === "order-status") return mutate(`/api/restaurant/orders/${button.dataset.id}/status`, "PATCH", { status: button.dataset.status });
  if (action === "toggle-item") return mutate(`/api/restaurant/restaurants/${state.workspace.restaurant.id}/menu/${button.dataset.id}`, "PATCH", { available: button.dataset.available === "true" });
  if (action === "edit-item-json") { const item = state.workspace.menu.find((i) => i.id === button.dataset.id); return showDialog(`<h2 id="dialog-title" tabindex="-1">Edit ${e(item.name)}</h2><form id="menu-edit" data-id="${e(item.id)}" class="stack"><label>Name<input class="field" name="name" value="${e(item.name)}" required></label><label>Description<textarea name="description">${e(item.description)}</textarea></label><label>Price (£)<input class="field" name="price" type="number" min="0" step="0.01" value="${(item.priceMinor/100).toFixed(2)}"></label><label>Category<input class="field" name="category" value="${e(item.category || "")}"></label><label>Allergens, comma separated<input class="field" name="allergens" value="${e(item.allergens?.join(", ") || "")}"></label><label>Dietary tags, comma separated<input class="field" name="dietaryTags" value="${e(item.dietaryTags?.join(", ") || "")}"></label><label>Modifier groups (validated JSON)<textarea class="code-field" name="modifierGroups">${e(JSON.stringify(item.modifierGroups ?? [], null, 2))}</textarea></label><button class="primary">Save item</button><div class="form-error"></div></form>`); }
  if (action === "approval") return mutate(`/api/admin/restaurants/${button.dataset.id}/approval`, "PATCH", { status: button.dataset.status });
  if (action === "settlement-dialog") return showSettlement(button.dataset.id);
  if (action === "suspension-dialog") return showSuspension(button.dataset.id, button.dataset.suspended === "true");
  if (action === "support-status") return mutate(`/api/admin/support/${button.dataset.id}`, "PATCH", { status: button.dataset.status });
  if (action === "deletion-dialog") return showDeletionReview(button.dataset.id);
  if (action === "test-notification") { if (!("Notification" in window)) return message("Browser notifications are unavailable here."); const permission = await Notification.requestPermission(); if (permission === "granted") new Notification("Calai Eats local test", { body: "Restaurant notifications are connected in this browser." }); else message("Notification permission was not granted."); return; }
  if (action === "order-detail") return showOrderDetail(state.workspace.orders.find((o) => o.id === button.dataset.id));
  if (action === "close-dialog") { if (event.target.closest("[data-dialog]") && !event.target.matches("[data-action=close-dialog]")) return; closeDialog(); }
});

document.addEventListener("input", (event) => { if (event.target.id === "restaurant-search") { state.search = event.target.value; const position = event.target.selectionStart; renderDiscover(); const restored = document.querySelector("#restaurant-search"); restored.focus(); restored.setSelectionRange(position, position); } if (event.target.id === "admin-order-search") { const q = event.target.value.toLowerCase(); document.querySelector("#admin-orders").innerHTML = state.workspace.orders.filter((o) => `${o.id} ${o.restaurantName}`.toLowerCase().includes(q)).map(adminOrderCard).join("") || `<div class="empty">No matching orders.</div>`; } if (event.target.classList.contains("margin-cost")) { const gross = Number(event.target.form.dataset.gross); const costs = [...event.target.form.querySelectorAll(".margin-cost")].map((input) => Math.round(Number(input.value || 0)*100)); document.querySelector("#margin-result").textContent = money(estimatedMargin(gross, Object.fromEntries(costs.map((v,i) => [i,v]))).estimatedMarginMinor); } });
document.addEventListener("change", (event) => { if (event.target.name === "fulfillment") { state.fulfillment = event.target.value; state.fulfillmentExplicit = true; renderMenu(); } if (event.target.id === "cuisine-filter") { state.cuisine = event.target.value; renderDiscover(); } if (event.target.dataset.modifierItem) { const itemId = event.target.dataset.modifierItem, groupId = event.target.dataset.modifierGroup; state.modifiers[itemId] ??= {}; const group = state.menu.find((i) => i.id === itemId)?.modifierGroups?.find((g) => g.id === groupId); if (event.target.type === "radio") state.modifiers[itemId][groupId] = event.target.value ? [event.target.value] : []; else { const selected = new Set(state.modifiers[itemId][groupId] ?? []); event.target.checked ? selected.add(event.target.value) : selected.delete(event.target.value); if (selected.size > group.maxSelections) { event.target.checked = false; message(`Choose up to ${group.maxSelections} for ${group.name}.`); return; } state.modifiers[itemId][groupId] = [...selected]; } renderMenu(); } });
document.addEventListener("submit", async (event) => {
  event.preventDefault(); const form = event.target;
  if (form.id === "postcode-form") { state.postcode = new FormData(form).get("postcode"); if (state.postcode && !state.fulfillmentExplicit) state.fulfillment = "delivery"; return loadDiscover(); }
  if (form.id === "login-form") return authSubmit(form, false);
  if (form.id === "register-form") return authSubmit(form, true);
  if (form.id === "restaurant-register-form") { const data = Object.fromEntries(new FormData(form)); const button = form.querySelector("button"); button.disabled = true; try { const result = await api("/api/auth/restaurant-register", { method: "POST", body: JSON.stringify(data) }); resetIdentity(result.user); await navigate("workspace"); } catch (error) { form.querySelector(".form-error").className = "form-error error"; form.querySelector(".form-error").textContent = error.message; button.disabled = false; } return; }
  if (form.id === "checkout-form") return submitOrder(form);
  if (form.id === "restaurant-create") return mutate("/api/restaurant/restaurants", "POST", { name: new FormData(form).get("name") });
  if (form.id === "menu-create" || form.id === "menu-edit") { const d = new FormData(form); const modifierGroups=readModifiers(form); const body = { name: d.get("name"), description: d.get("description"), priceMinor: Math.round(Number(d.get("price"))*100), category: d.get("category"), allergens: d.get("allergens").split(",").map((x)=>x.trim()).filter(Boolean), dietaryTags: d.get("dietaryTags").split(",").map((x)=>x.trim()).filter(Boolean), modifierGroups }; if (form.id === "menu-edit") { closeDialog(); return mutate(`/api/restaurant/restaurants/${state.workspace.restaurant.id}/menu/${form.dataset.id}`, "PATCH", body); } return mutate(`/api/restaurant/restaurants/${state.workspace.restaurant.id}/menu`, "POST", body); }
  if (form.id === "delivery-form") { const d = new FormData(form); return mutate(`/api/restaurant/restaurants/${state.workspace.restaurant.id}/delivery`, "PATCH", { enabled: d.get("enabled") === "on", outcodes: d.get("outcodes").split(",").map((x) => x.trim()).filter(Boolean), deliveryFeeMinor: Math.round(Number(d.get("fee"))*100), minDeliverySubtotalMinor: Math.round(Number(d.get("minimum"))*100) }); }
  if (form.id === "profile-form") { const d = new FormData(form); const openingHours=readHours(form); return mutate(`/api/restaurant/restaurants/${state.workspace.restaurant.id}/profile`, "PATCH", { name:d.get("name"), cuisine:d.get("cuisine"), description:d.get("description"), phone:d.get("phone"), address:d.get("address"), estimatedDeliveryMinutes:Number(d.get("estimatedDeliveryMinutes")), estimatedCollectionMinutes:Number(d.get("estimatedCollectionMinutes")), busyMinutes:Number(d.get("busyMinutes")), holidayDates:d.get("holidayDates").split(",").map((x)=>x.trim()).filter(Boolean), openingHours, collectionEnabled:d.get("collectionEnabled")==="on", cashEnabled:d.get("cashEnabled")==="on", paused:d.get("paused")==="on", alwaysOpen:d.get("alwaysOpen")==="on" }); }
  if (form.id === "staff-form") { const d = Object.fromEntries(new FormData(form)); return mutate(`/api/restaurant/restaurants/${state.workspace.restaurant.id}/staff`, "POST", d); }
  if (form.id === "offer-form") { const d = new FormData(form); const body = { customerIds:d.getAll("customerIds"), title:d.get("title"), message:d.get("message"), menuItemId:d.get("menuItemId"), minSubtotalMinor:Math.round(Number(d.get("minimum"))*100), expiresInDays:Number(d.get("expiresInDays")) }; const fingerprint=JSON.stringify(body); if(form.dataset.fingerprint!==fingerprint){form.dataset.fingerprint=fingerprint;form.dataset.key=createRequestKey("offer");} const button=form.querySelector("button");button.disabled=true;try{await api(`/api/restaurant/restaurants/${state.workspace.restaurant.id}/offers`,{method:"POST",headers:{"Idempotency-Key":form.dataset.key},body:JSON.stringify(body)});message("Offer sent in the local app.");await loadWorkspace();}catch(error){const box=form.querySelector(".form-error");box.className="form-error error full";box.textContent=`${error.message} You can retry safely.`;button.disabled=false;}return; }
  if (form.id === "account-form") { const d = Object.fromEntries(new FormData(form)); try { await api("/api/account", { method:"PATCH", body:JSON.stringify(d) }); message("Account updated."); await loadAccount(); } catch(error){ message(error.message); } return; }
  if (form.id === "support-form") { const d = Object.fromEntries(new FormData(form)); if (!d.orderId) delete d.orderId; try { await api("/api/support", { method:"POST", body:JSON.stringify(d) }); message("Support request sent."); await loadAccount(); } catch(error){ message(error.message); } return; }
  if (form.id === "deletion-form") { const d = Object.fromEntries(new FormData(form)); try { await api("/api/account/deletion-requests", { method:"POST", body:JSON.stringify(d) }); message("Deletion review requested."); await loadAccount(); } catch(error){ message(error.message); } return; }
  if (form.id === "refund-form" || form.id === "settlement-form") { const d = new FormData(form); const body = form.id === "refund-form" ? { foodAmountMinor: Math.round(Number(d.get("food"))*100), deliveryAmountMinor: Math.round(Number(d.get("delivery"))*100), reason:d.get("reason") } : { amountMinor:Math.round(Number(d.get("amount"))*100), reference:d.get("reference") }; const fingerprint = JSON.stringify(body); if (form.dataset.fingerprint !== fingerprint) { form.dataset.fingerprint = fingerprint; form.dataset.key = createRequestKey(form.id === "refund-form" ? "refund" : "settlement"); } const button=form.querySelector("button[type=submit],button.primary"); button.disabled=true; try { const path=form.id === "refund-form" ? `/api/admin/orders/${form.dataset.id}/refunds` : `/api/admin/restaurants/${form.dataset.id}/cash-settlements`; await api(path,{method:"POST",headers:{"Idempotency-Key":form.dataset.key},body:JSON.stringify(body)}); closeDialog(); message("Saved."); await loadWorkspace(); } catch(error){ const box=form.querySelector(".form-error"); box.className="form-error error"; box.textContent=`${error.message} You can retry safely.`; button.disabled=false; } return; }
  if (form.id === "suspension-form") { const d = new FormData(form); closeDialog(); return mutate(`/api/admin/restaurants/${form.dataset.id}/suspension`, "PATCH", { suspended:form.dataset.suspended === "true", reason:d.get("reason") }); }
  if (form.id === "deletion-review-form") { const d = Object.fromEntries(new FormData(form)); closeDialog(); return mutate(`/api/admin/deletion-requests/${form.dataset.id}`, "PATCH", d); }
});
window.addEventListener("online", () => { document.querySelector("#network").hidden = true; message("Back online."); });
window.addEventListener("offline", () => { document.querySelector("#network").hidden = false; });
document.addEventListener("keydown", (event) => { const dialog=document.querySelector("[data-dialog]"); if (event.key === "Escape" && dialog) { closeDialog(); return; } if (event.key === "Tab" && dialog) { const focusable=[...dialog.querySelectorAll("button,input,select,textarea,a[href]")].filter((node)=>!node.disabled); if (!focusable.length) return; const first=focusable[0], last=focusable.at(-1); if (event.shiftKey && document.activeElement===first) { event.preventDefault(); last.focus(); } else if (!event.shiftKey && document.activeElement===last) { event.preventDefault(); first.focus(); } } });
boot();
